use xiom.io;
fn scores_to_grades(scores: &Vec[Int]) -> Vec[Str] {
  let result: Vec[Str] = Vec[Str].new();
  let i = 0;
  while i < scores.len() {
    let s = match scores.get(i) { Some(v) => v, None => 0 };
    let grade = "F";
    if s >= 90 { grade = "A"; }
    else if s >= 80 { grade = "B"; }
    else if s >= 70 { grade = "C"; }
    result.push(grade);
    i = i + 1;
  }
  return result;
}

fn entries_to_lines(entries: &Map[Str, Str], keys: &Vec[Str]) -> Vec[Str] {
  let result: Vec[Str] = Vec[Str].new();
  let i = 0;
  while i < keys.len() {
    let key = match keys.get(i) { Some(k) => k, None => "" };
    let val = match entries.get(&key) { Some(v) => v, None => "?" };
    result.push(key + ": " + val);
    i = i + 1;
  }
  return result;
}

fn main() -> Int {
  let scores: Vec[Int] = Vec[Int].new();
  scores.push(95); scores.push(82); scores.push(73); scores.push(60);
  let grades = scores_to_grades(&scores);
  io.println(match grades.get(0) { Some(g) => g, None => "?" }.to_str());
  return 0;
}
